import{L as e,b as t,x as n}from"./vue-Dpdj5O0f.js";import{oi as r}from"./common-DOddpOND.js";var i=JSON.parse(`{"path":"/os/dsm/ghs1ig04/","title":"设置反向代理服务器 | DSM","lang":"zh-CN","frontmatter":{"title":"设置反向代理服务器","createTime":"2026/08/29 21:58:43","permalink":"/os/dsm/ghs1ig04/"},"readingTime":{"minutes":4.38,"words":1313},"git":{},"filePathRelative":"os/dsm/003.synology-dsm72-reverse-proxy.md","headers":[]}`),a={name:`003.synology-dsm72-reverse-proxy.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>通过群晖 DSM 7.2 的反向代理功能，可以用一个端口（或配合运营商放行的 80/443 实现零端口）访问群晖上的多个服务。本文记录 DSM 端反向代理规则的配置，以及运营商处二级域名（CNAME）解析的设置。零端口访问的前提是运营商已开放 80/443 端口，配置步骤本身不变。</p><h2 id="一、群晖端反向代理设置" tabindex="-1"><a class="header-anchor" href="#一、群晖端反向代理设置"><span>一、群晖端反向代理设置</span></a></h2><ol><li><p>打开反向代理配置：<code>控制面板</code> → <code>登录门户</code> → <code>高级</code> → <code>反向代理服务器</code>。</p></li><li><p>新增一条反向代理规则，按以下界面填写：</p></li></ol><div style="font-family:-apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Roboto, &#39;Helvetica Neue&#39;, Arial, sans-serif;background-color:#f1f5f9;padding:20px;display:flex;justify-content:center;"><div style="background:#ffffff;border-radius:8px;box-shadow:0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);width:100%;max-width:560px;overflow:hidden;border:1px solid #e2e8f0;"><div style="display:flex;justify-content:space-between;align-items:center;padding:16px 24px;border-bottom:1px solid #e2e8f0;"><h2 style="font-size:16px;font-weight:600;color:#1e293b;margin:0;">反向代理服务器规则</h2><span style="font-size:20px;color:#64748b;cursor:pointer;line-height:1;">×</span></div><div style="display:flex;gap:24px;padding:0 24px;border-bottom:1px solid #e2e8f0;background:#fff;"><div style="padding:12px 0;font-size:14px;font-weight:500;color:#0076ff;border-bottom:2px solid #0076ff;margin-bottom:-1px;">常规</div><div style="padding:12px 0;font-size:14px;font-weight:500;color:#64748b;">自定义标题</div><div style="padding:12px 0;font-size:14px;font-weight:500;color:#64748b;">高级设置</div></div><div style="padding:24px;display:flex;flex-direction:column;gap:16px;"><div style="display:grid;grid-template-columns:140px 1fr;align-items:center;gap:12px;"><label style="font-size:14px;color:#1e293b;">反向代理服务器名称：</label><input type="text" value="MyService" style="width:100%;padding:8px 12px;font-size:14px;border:1px solid #cbd5e1;border-radius:6px;outline:none;color:#1e293b;background:#fff;"></div><div style="font-size:15px;font-weight:600;color:#0076ff;margin-top:8px;padding-bottom:6px;border-bottom:1px dashed #e2e8f0;">来源</div><div style="display:grid;grid-template-columns:140px 1fr;align-items:center;gap:12px;"><label style="font-size:14px;color:#1e293b;">协议：</label><select style="width:100%;padding:8px 12px;font-size:14px;border:1px solid #cbd5e1;border-radius:6px;outline:none;color:#1e293b;background:#fff;"><option selected>HTTPS</option><option>HTTP</option></select></div><div style="display:grid;grid-template-columns:140px 1fr;align-items:center;gap:12px;"><label style="font-size:14px;color:#1e293b;">主机名：</label><input type="text" value="subdomain.your-domain" style="width:100%;padding:8px 12px;font-size:14px;border:1px solid #cbd5e1;border-radius:6px;outline:none;color:#1e293b;background:#fff;"></div><div style="display:grid;grid-template-columns:140px 1fr;align-items:center;gap:12px;"><label style="font-size:14px;color:#1e293b;">端口：</label><input type="text" value="443" style="width:100%;padding:8px 12px;font-size:14px;border:1px solid #cbd5e1;border-radius:6px;outline:none;color:#1e293b;background:#fff;"></div><div style="display:grid;grid-template-columns:140px 1fr;align-items:center;gap:12px;"><div></div><label style="display:flex;align-items:center;gap:8px;font-size:14px;color:#1e293b;cursor:pointer;"><input type="checkbox" style="width:16px;height:16px;"> 启用 HSTS </label></div><div style="display:grid;grid-template-columns:140px 1fr;align-items:center;gap:12px;"><label style="font-size:14px;color:#1e293b;">访问控制配置文件：</label><div style="display:flex;align-items:center;gap:6px;"><select style="flex:1;padding:8px 12px;font-size:14px;border:1px solid #cbd5e1;border-radius:6px;outline:none;color:#1e293b;background:#fff;"><option selected>未配置</option></select><span style="display:inline-flex;justify-content:center;align-items:center;width:18px;height:18px;border-radius:50%;background-color:#e0f2fe;color:#0284c7;font-size:12px;font-weight:bold;">i</span></div></div><div style="font-size:15px;font-weight:600;color:#0076ff;margin-top:8px;padding-bottom:6px;border-bottom:1px dashed #e2e8f0;">目的地</div><div style="display:grid;grid-template-columns:140px 1fr;align-items:center;gap:12px;"><label style="font-size:14px;color:#1e293b;">协议：</label><select style="width:100%;padding:8px 12px;font-size:14px;border:1px solid #cbd5e1;border-radius:6px;outline:none;color:#1e293b;background:#fff;"><option selected>HTTP</option><option>HTTPS</option></select></div><div style="display:grid;grid-template-columns:140px 1fr;align-items:center;gap:12px;"><label style="font-size:14px;color:#1e293b;">主机名：</label><input type="text" value="localhost" style="width:100%;padding:8px 12px;font-size:14px;border:1px solid #cbd5e1;border-radius:6px;outline:none;color:#1e293b;background:#fff;"></div><div style="display:grid;grid-template-columns:140px 1fr;align-items:center;gap:12px;"><label style="font-size:14px;color:#1e293b;">端口：</label><input type="text" value="3003" style="width:100%;padding:8px 12px;font-size:14px;border:1px solid #cbd5e1;border-radius:6px;outline:none;color:#1e293b;background:#fff;"></div></div><div style="display:flex;justify-content:flex-end;gap:12px;padding:16px 24px;background-color:#f8fafc;border-top:1px solid #e2e8f0;"><button style="padding:8px 20px;font-size:14px;font-weight:500;border-radius:6px;border:1px solid transparent;background-color:#e2e8f0;color:#475569;cursor:pointer;">取消</button><button style="padding:8px 20px;font-size:14px;font-weight:500;border-radius:6px;border:1px solid transparent;background-color:#0076ff;color:#ffffff;cursor:pointer;">保存</button></div></div></div><p>保存后规则即生效，外部通过 <code>https://subdomain.your-domain</code> 即可访问对应内网服务。来源端口填 <code>443</code> 且运营商已放行 443 时为零端口访问；否则带自定义端口（如 12443）。每条服务建一条规则，来源子域名互不相同即可。</p><h2 id="二、域名运营商解析二级域名" tabindex="-1"><a class="header-anchor" href="#二、域名运营商解析二级域名"><span>二、域名运营商解析二级域名</span></a></h2><p>在域名运营商处添加 CNAME 记录，将二级域名指向你的服务器主域名。以阿里云为例：</p><table><thead><tr><th>记录类型</th><th>主机记录</th><th>记录值</th><th>TTL</th></tr></thead><tbody><tr><td>CNAME</td><td>subdomain</td><td>your-domain</td><td>默认</td></tr></tbody></table><p>即把 <code>subdomain.your-domain</code> 解析到群晖所在的主域名，再由群晖反向代理按子域名分发到对应内网服务。</p><div class="hint-container note"><p class="hint-container-title">笔记</p><p>不同运营商控制台措辞略有差异（腾讯云、Cloudflare 等同为 CNAME 记录），字段含义一致：主机记录即二级子域名前缀，记录值填主域名。</p></div>`,11)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};